fun twoSum(nums: IntArray, target: Int): IntArray {
    val seen = HashMap<Int, Int>()          // O(n) space
    for ((i, x) in nums.withIndex()) {      // O(n) time
        val need = target - x
        seen[need]?.let { return intArrayOf(it, i) }
        seen[x] = i
    }
    return intArrayOf()
}
// Time: O(n)   Space: O(n)
